    70→// fileExists checks if a file exists
    71→func fileExists(path string) bool {
    72→	_, err := os.Stat(path)
    73→	return err == nil
    74→}
    75→
    76→// copyFile copies a file from src to dst using os.Root for traversal-resistant
    77→// writes (Go 1.24+). dst must be absolute and reside under either the repo
    78→// worktree root, the user's home directory (for agent session dirs such as
    79→// ~/.claude/), or the system temp directory (used during tests).
    80→// The kernel enforces that the write cannot escape the allowed directory,
    81→// eliminating TOCTOU races and symlink escapes.
    82→func copyFile(src, dst string) error {
    83→	src = filepath.Clean(src)
    84→	dst = filepath.Clean(dst)
    85→
    86→	if !filepath.IsAbs(dst) {
    87→		return fmt.Errorf("copyFile: dst must be absolute, got %q", dst)
    88→	}
    89→
    90→	input, err := os.ReadFile(src)
    91→	if err != nil {
    92→		return err //nolint:wrapcheck // already present in codebase
    93→	}
    94→
    95→	root, relPath, err := openAllowedRoot(dst)
    96→	if err != nil {
    97→		return err
    98→	}
    99→	defer root.Close()
   100→
   101→	if err := osroot.WriteFile(root, relPath, input, 0o600); err != nil {
   102→		return fmt.Errorf("failed to write file: %w", err)
   103→	}
   104→	return nil
   105→}
   106→
   107→// openAllowedRoot finds the allowed root directory that contains dst and returns
   108→// an os.Root handle along with the relative path within that root.
   109→// Allowed directories: repo worktree root, user home, system temp dir.
   110→// dst is resolved through symlinks before matching to handle macOS /var → /private/var.
   111→func openAllowedRoot(dst string) (*os.Root, string, error) {
   112→	allowed := allowedRootDirs()
   113→
   114→	// Resolve the directory portion of dst through symlinks so that e.g.
   115→	// /var/folders/... matches /private/var/folders/... on macOS.
   116→	// Only the parent directory is resolved; the final component may not exist yet.
   117→	resolvedDst := dst
   118→	if r, err := filepath.EvalSymlinks(filepath.Dir(dst)); err == nil {
   119→		resolvedDst = filepath.Join(r, filepath.Base(dst))
   120→	}
   121→
   122→	for _, dir := range allowed {
   123→		if !paths.IsSubpath(dir, resolvedDst) {
   124→			continue
   125→		}
   126→		rel, err := filepath.Rel(dir, resolvedDst)
   127→		if err != nil {
   128→			continue
   129→		}
   130→		root, err := os.OpenRoot(dir)
   131→		if err != nil {
   132→			return nil, "", fmt.Errorf("openAllowedRoot: failed to open root %q: %w", dir, err)
   133→		}
   134→		return root, rel, nil
   135→	}
   136→
   137→	return nil, "", fmt.Errorf("openAllowedRoot: dst %q is outside allowed directories", dst)
   138→}
   139→
   140→// allowedRootDirs returns the list of directories that copyFile may write to.
   141→// Directories are resolved through symlinks so they match resolved dst paths.
   142→func allowedRootDirs() []string {
   143→	allowed := make([]string, 0, 3)
   144→
   145→	if repoRoot, err := paths.WorktreeRoot(context.Background()); err == nil {
   146→		allowed = appendResolved(allowed, repoRoot)
   147→	}
   148→	if home, err := os.UserHomeDir(); err == nil {
   149→		allowed = appendResolved(allowed, home)
   150→	}
   151→	if tmpDir := os.TempDir(); tmpDir != "" {
   152→		allowed = appendResolved(allowed, tmpDir)
   153→	}
   154→
   155→	return allowed
   156→}
   157→
   158→// appendResolved appends dir to the list after resolving symlinks.
   159→// Falls back to the original path if symlink resolution fails.
   160→func appendResolved(dirs []string, dir string) []string {
   161→	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
   162→		return append(dirs, resolved)
   163→	}
   164→	return append(dirs, dir)
   165→}
