   362→// FilterAndNormalizePaths converts absolute paths to relative and filters out
   363→// infrastructure paths and paths outside the repo.
   364→func FilterAndNormalizePaths(files []string, cwd string) []string {
   365→	var result []string
   366→	for _, file := range files {
   367→		relPath := paths.ToRelativePath(file, cwd)
   368→		if relPath == "" {
   369→			continue // outside repo
   370→		}
   371→		if paths.IsInfrastructurePath(relPath) {
   372→			continue // skip .entire directory
   373→		}
   374→		result = append(result, filepath.ToSlash(relPath))
   375→	}
   376→	return result
   377→}
