   457→// CapturePreTaskState captures current untracked files before a Task execution
   458→// and saves them to a state file.
   459→// Works correctly from any subdirectory within the repository.
   460→func CapturePreTaskState(ctx context.Context, toolUseID string) error {
   461→	if toolUseID == "" {
   462→		return errors.New("tool_use_id is required")
   463→	}
   464→
   465→	if err := validation.ValidateToolUseID(toolUseID); err != nil {
   466→		return fmt.Errorf("invalid tool use ID for pre-task state: %w", err)
   467→	}
   468→
   469→	// Get absolute path for tmp directory
   470→	tmpDirAbs := resolveTmpDir(ctx)
   471→
   472→	// Create tmp directory if it doesn't exist
   473→	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
   474→		return fmt.Errorf("failed to create tmp directory: %w", err)
   475→	}
   476→
   477→	// Get list of untracked files (excluding .entire directory itself)
   478→	untrackedFiles, err := getUntrackedFilesForState(ctx)
   479→	if err != nil {
   480→		return fmt.Errorf("failed to get untracked files: %w", err)
   481→	}
   482→
   483→	// Create state file using os.Root for traversal-resistant write
   484→	state := PreTaskState{
   485→		ToolUseID:      toolUseID,
   486→		Timestamp:      time.Now().UTC().Format(time.RFC3339),
   487→		UntrackedFiles: untrackedFiles,
   488→	}
   489→
   490→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
   491→	if err != nil {
   492→		return fmt.Errorf("failed to marshal state: %w", err)
   493→	}
   494→
   495→	fileName := fmt.Sprintf("pre-task-%s.json", toolUseID)
   496→	root, err := os.OpenRoot(tmpDirAbs)
   497→	if err != nil {
   498→		return fmt.Errorf("failed to open tmp directory root: %w", err)
   499→	}
   500→	defer root.Close()
   501→
   502→	if err := osroot.WriteFile(root, fileName, data, 0o600); err != nil {
   503→		return fmt.Errorf("failed to write state file: %w", err)
   504→	}
   505→
   506→	logging.Debug(logging.WithComponent(ctx, "state"), "captured state before task",
   507→		slog.Int("untracked_files", len(untrackedFiles)))
   508→	return nil
   509→}
