   567→// preTaskFilePrefix is the prefix for pre-task state files
   568→const preTaskFilePrefix = "pre-task-"
   569→
   570→// FindActivePreTaskFile finds an active pre-task file in .entire/tmp/ and returns
   571→// the parent Task's tool_use_id. Returns ("", false) if no pre-task file exists.
   572→// When multiple pre-task files exist (nested subagents), returns the most recently
   573→// modified one.
   574→// Works correctly from any subdirectory within the repository.
   575→func FindActivePreTaskFile(ctx context.Context) (taskToolUseID string, found bool) {
   576→	tmpDirAbs := resolveTmpDir(ctx)
   577→	entries, err := os.ReadDir(tmpDirAbs)
   578→	if err != nil {
   579→		return "", false
   580→	}
   581→
   582→	var latestFile string
   583→	var latestTime time.Time
   584→
   585→	for _, entry := range entries {
   586→		if entry.IsDir() {
   587→			continue
   588→		}
   589→		name := entry.Name()
   590→		if !strings.HasPrefix(name, preTaskFilePrefix) || !strings.HasSuffix(name, ".json") {
   591→			continue
   592→		}
   593→
   594→		// Check modification time for nested subagent handling
   595→		info, err := entry.Info()
   596→		if err != nil {
   597→			continue
   598→		}
   599→		if latestFile == "" || info.ModTime().After(latestTime) {
   600→			latestFile = name
   601→			latestTime = info.ModTime()
   602→		}
   603→	}
   604→
   605→	if latestFile == "" {
   606→		return "", false
   607→	}
   608→
   609→	// Extract tool_use_id from filename: pre-task-<tool_use_id>.json
   610→	toolUseID := strings.TrimPrefix(latestFile, preTaskFilePrefix)
   611→	toolUseID = strings.TrimSuffix(toolUseID, ".json")
   612→	return toolUseID, true
   613→}
