   615→// GetNextCheckpointSequence returns the next sequence number for incremental checkpoints.
   616→// It counts existing checkpoint files in the task metadata checkpoints directory.
   617→// Returns 1 if no checkpoints exist yet.
   618→func GetNextCheckpointSequence(sessionID, taskToolUseID string) int {
   619→	// Use the session ID directly as the metadata directory name
   620→	sessionMetadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
   621→	taskMetadataDir := strategy.TaskMetadataDir(sessionMetadataDir, taskToolUseID)
   622→	checkpointsDir := filepath.Join(taskMetadataDir, "checkpoints")
   623→
   624→	entries, err := os.ReadDir(checkpointsDir)
   625→	if err != nil {
   626→		// Directory doesn't exist or can't be read - start at 1
   627→		return 1
   628→	}
   629→
   630→	// Count JSON files (checkpoints)
   631→	count := 0
   632→	for _, entry := range entries {
   633→		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") {
   634→			count++
   635→		}
   636→	}
   637→
   638→	return count + 1
   639→}
