   335→// runScenario runs the test function and recovers from errScenarioRestart
   336→// panics triggered by transient API errors in RunPrompt. Returns true if
   337→// the scenario should be restarted with a fresh repository.
   338→func runScenario(t *testing.T, s *RepoState, ctx context.Context, fn func(t *testing.T, s *RepoState, ctx context.Context)) (restarted bool) {
   339→	t.Helper()
   340→	defer func() {
   341→		if r := recover(); r != nil {
   342→			if _, ok := r.(errScenarioRestart); ok {
   343→				restarted = true
   344→				return
   345→			}
   346→			panic(r) // re-panic for unexpected panics
   347→		}
   348→	}()
   349→	fn(t, s, ctx)
   350→	return false
   351→}
