   121→// WaitForNoShadowBranches polls until all shadow branches are cleaned up or
   122→// the timeout expires. Shadow branch cleanup can lag slightly behind checkpoint
   123→// condensation (carry-forward creates intermediate branches that are deleted
   124→// asynchronously).
   125→func WaitForNoShadowBranches(t *testing.T, dir string, timeout time.Duration) {
   126→	t.Helper()
   127→	deadline := time.Now().Add(timeout)
   128→	for time.Now().Before(deadline) {
   129→		shadow := shadowBranches(t, dir)
   130→		if len(shadow) == 0 {
   131→			return
   132→		}
   133→		time.Sleep(200 * time.Millisecond)
   134→	}
   135→	shadow := shadowBranches(t, dir)
   136→	require.Emptyf(t, shadow,
   137→		"shadow branches should be cleaned up within %s after commit, found: %v", timeout, shadow)
   138→}
