   184→// CalculateTokenUsageFromFile calculates token usage from a Claude Code transcript file.
   185→// If startLine > 0, only considers lines from startLine onwards.
   186→func CalculateTokenUsageFromFile(path string, startLine int) (*agent.TokenUsage, error) {
   187→	if path == "" {
   188→		return &agent.TokenUsage{}, nil
   189→	}
   190→
   191→	lines, err := transcript.ParseFromFileAtLine(path, startLine)
   192→	if err != nil {
   193→		return nil, err //nolint:wrapcheck // caller adds context
   194→	}
   195→
   196→	return CalculateTokenUsage(lines), nil
   197→}
