   267→// extractAgentIDFromText extracts an agent ID from text containing "agentId: <id>".
   268→func extractAgentIDFromText(text string) string {
   269→	const prefix = "agentId: "
   270→	idx := strings.Index(text, prefix)
   271→	if idx == -1 {
   272→		return ""
   273→	}
   274→
   275→	// Extract the ID (alphanumeric characters after the prefix)
   276→	start := idx + len(prefix)
   277→	end := start
   278→	for end < len(text) && (text[end] >= 'a' && text[end] <= 'z' ||
   279→		text[end] >= 'A' && text[end] <= 'Z' ||
   280→		text[end] >= '0' && text[end] <= '9') {
   281→		end++
   282→	}
   283→
   284→	if end > start {
   285→		return text[start:end]
   286→	}
   287→	return ""
   288→}
