   335→// ExtractAllModifiedFiles extracts files modified by both the main agent and
   336→// any subagents spawned via the Task tool. It parses the main transcript bytes from
   337→// startLine, collects modified files from the main agent, then reads each
   338→// subagent's transcript from subagentsDir to collect their modified files too.
   339→// The result is a deduplicated list of all modified file paths.
   340→func (c *ClaudeCodeAgent) ExtractAllModifiedFiles(transcriptData []byte, startLine int, subagentsDir string) ([]string, error) {
   341→	if len(transcriptData) == 0 {
   342→		return nil, nil
   343→	}
   344→
   345→	// Slice to the relevant portion and parse
   346→	sliced := transcript.SliceFromLine(transcriptData, startLine)
   347→	parsed, err := transcript.ParseFromBytes(sliced)
   348→	if err != nil {
   349→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
   350→	}
   351→
   352→	// Collect modified files from main agent
   353→	fileSet := make(map[string]bool)
   354→	var files []string
   355→	for _, f := range ExtractModifiedFiles(parsed) {
   356→		if !fileSet[f] {
   357→			fileSet[f] = true
   358→			files = append(files, f)
   359→		}
   360→	}
   361→
   362→	// Find spawned subagents and collect their modified files (skip when subagentsDir is empty to avoid reading from cwd)
   363→	agentIDs := ExtractSpawnedAgentIDs(parsed)
   364→	if subagentsDir == "" {
   365→		return files, nil
   366→	}
   367→	for agentID := range agentIDs {
   368→		agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
   369→		agentLines, agentErr := transcript.ParseFromFileAtLine(agentPath, 0)
   370→		if agentErr != nil {
   371→			// Subagent transcript may not exist yet or may have been cleaned up
   372→			continue
   373→		}
   374→		for _, f := range ExtractModifiedFiles(agentLines) {
   375→			if !fileSet[f] {
   376→				fileSet[f] = true
   377→				files = append(files, f)
   378→			}
   379→		}
   380→	}
   381→
   382→	return files, nil
   383→}
