   288→// filterToUncommittedFiles removes files from the list that are already committed to HEAD
   289→// with matching content. This prevents re-adding files that an agent committed mid-turn
   290→// (already condensed by PostCommit) back to FilesTouched via SaveStep. Files not in
   291→// HEAD or with different content in the working tree are kept. Fails open: if any git
   292→// operation errors, returns the original list unchanged.
   293→func filterToUncommittedFiles(ctx context.Context, files []string, repoRoot string) []string {
   294→	if len(files) == 0 {
   295→		return files
   296→	}
   297→
   298→	repo, err := openRepository(ctx)
   299→	if err != nil {
   300→		return files // fail open
   301→	}
   302→
   303→	head, err := repo.Head()
   304→	if err != nil {
   305→		return files // fail open (empty repo, detached HEAD, etc.)
   306→	}
   307→
   308→	commit, err := repo.CommitObject(head.Hash())
   309→	if err != nil {
   310→		return files // fail open
   311→	}
   312→
   313→	headTree, err := commit.Tree()
   314→	if err != nil {
   315→		return files // fail open
   316→	}
   317→
   318→	var result []string
   319→	for _, relPath := range files {
   320→		headFile, err := headTree.File(relPath)
   321→		if err != nil {
   322→			// File not in HEAD — it's uncommitted
   323→			result = append(result, relPath)
   324→			continue
   325→		}
   326→
   327→		// File is in HEAD — compare content with working tree
   328→		absPath := filepath.Join(repoRoot, relPath)
   329→		workingContent, err := os.ReadFile(absPath) //nolint:gosec // path from controlled source
   330→		if err != nil {
   331→			// Can't read working tree file (deleted?) — keep it
   332→			result = append(result, relPath)
   333→			continue
   334→		}
   335→
   336→		headContent, err := headFile.Contents()
   337→		if err != nil {
   338→			result = append(result, relPath)
   339→			continue
   340→		}
   341→
   342→		// Normalize CRLF→LF for text files before comparing: on Windows, agents
   343→		// (Node.js) may write files with CRLF, but git stores blobs with LF after
   344→		// autocrlf normalization. A raw byte comparison would falsely treat the file
   345→		// as uncommitted. Binary files (containing null bytes) are left unchanged.
   346→		workingStr := string(workingContent)
   347→		headStr := headContent
   348→		if !strings.Contains(workingStr, "\x00") {
   349→			workingStr = strings.ReplaceAll(workingStr, "\r\n", "\n")
   350→			headStr = strings.ReplaceAll(headStr, "\r\n", "\n")
   351→		}
   352→		if workingStr != headStr {
   353→			// Working tree differs from HEAD — uncommitted changes
   354→			result = append(result, relPath)
   355→		}
   356→		// else: content matches HEAD — already committed, skip
   357→	}
   358→
   359→	return result
   360→}
