   143→// IsSubpath reports whether child is lexically under parent (or equal to it).
   144→// It uses filepath.Rel, which cleans both inputs and is traversal-resistant:
   145→// a crafted child like "/a/b/../../../etc/passwd" that escapes parent will
   146→// produce a relative path starting with ".." and be rejected.
   147→func IsSubpath(parent, child string) bool {
   148→	rel, err := filepath.Rel(parent, child)
   149→	if err != nil {
   150→		return false
   151→	}
   152→	return rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
   153→}
