   379→// mergeUnique appends elements from extra into base, skipping duplicates already in base.
   380→func mergeUnique(base, extra []string) []string {
   381→	if len(extra) == 0 {
   382→		return base
   383→	}
   384→	seen := make(map[string]bool, len(base))
   385→	for _, s := range base {
   386→		seen[s] = true
   387→	}
   388→	for _, s := range extra {
   389→		if !seen[s] {
   390→			seen[s] = true
   391→			base = append(base, s)
   392→		}
   393→	}
   394→	return base
   395→}
