    23→// SerializeTranscript converts transcript lines back to JSONL bytes
    24→func SerializeTranscript(lines []TranscriptLine) ([]byte, error) {
    25→	var buf bytes.Buffer
    26→	for _, line := range lines {
    27→		data, err := json.Marshal(line)
    28→		if err != nil {
    29→			return nil, fmt.Errorf("failed to marshal line: %w", err)
    30→		}
    31→		buf.Write(data)
    32→		buf.WriteByte('\n')
    33→	}
    34→	return buf.Bytes(), nil
    35→}
