   184→func TestFilterAndNormalizePaths_SiblingDirectories(t *testing.T) {
   185→	// This test verifies the fix for the bug where files in sibling directories
   186→	// were filtered out when Claude runs from a subdirectory.
   187→	// When Claude is in /repo/frontend and edits /repo/api/file.ts,
   188→	// the relative path would be ../api/file.ts which was incorrectly filtered.
   189→	// The fix uses repo root instead of cwd, so paths should be api/file.ts.
   190→
   191→	tests := []struct {
   192→		name     string
   193→		files    []string
   194→		basePath string // simulates repo root or cwd
   195→		want     []string
   196→	}{
   197→		{
   198→			name: "files in sibling directories with repo root base",
   199→			files: []string{
   200→				"/repo/api/src/lib/github.ts",
   201→				"/repo/api/src/types.ts",
   202→				"/repo/frontend/src/pages/api.ts",
   203→			},
   204→			basePath: "/repo", // repo root
   205→			want: []string{
   206→				"api/src/lib/github.ts",
   207→				"api/src/types.ts",
   208→				"frontend/src/pages/api.ts",
   209→			},
   210→		},
   211→		{
   212→			name: "files in sibling directories with subdirectory base (old buggy behavior)",
   213→			files: []string{
   214→				"/repo/api/src/lib/github.ts",
   215→				"/repo/frontend/src/pages/api.ts",
   216→			},
   217→			basePath: "/repo/frontend", // cwd in subdirectory
   218→			want: []string{
   219→				// Only frontend file should remain, api file gets filtered
   220→				// because ../api/... starts with ..
   221→				"src/pages/api.ts",
   222→			},
   223→		},
   224→		{
   225→			name: "relative paths pass through unchanged",
   226→			files: []string{
   227→				"src/file.ts",
   228→				"lib/util.go",
   229→			},
   230→			basePath: "/repo",
   231→			want: []string{
   232→				"src/file.ts",
   233→				"lib/util.go",
   234→			},
   235→		},
   236→		{
   237→			// On Windows, git status returns paths with backslashes (e.g., "src\file.ts").
   238→			// filepath.ToSlash normalizes these to forward slashes for consistent storage.
   239→			// On Linux/macOS, filepath.Separator is already '/', so ToSlash is a no-op —
   240→			// we use strings.ReplaceAll to simulate the Windows input on all platforms.
   241→			name: "platform separator paths are normalized to forward slashes",
   242→			files: []string{
   243→				"src" + string(filepath.Separator) + "file.ts",
   244→				"lib" + string(filepath.Separator) + "nested" + string(filepath.Separator) + "util.go",
   245→			},
   246→			basePath: "/repo",
   247→			want: []string{
   248→				"src/file.ts",
   249→				"lib/nested/util.go",
   250→			},
   251→		},
   252→		{
   253→			name: "infrastructure paths are filtered",
   254→			files: []string{
   255→				"/repo/src/file.ts",
   256→				"/repo/.entire/metadata/session.json",
   257→			},
   258→			basePath: "/repo",
   259→			want: []string{
   260→				"src/file.ts",
   261→				// .entire path should be filtered
   262→			},
   263→		},
   264→	}
   265→
   266→	for _, tt := range tests {
   267→		t.Run(tt.name, func(t *testing.T) {
   268→			got := FilterAndNormalizePaths(tt.files, tt.basePath)
   269→			if len(got) != len(tt.want) {
   270→				t.Errorf("FilterAndNormalizePaths() returned %d files, want %d\ngot: %v\nwant: %v",
   271→					len(got), len(tt.want), got, tt.want)
   272→				return
   273→			}
   274→			for i, want := range tt.want {
   275→				if got[i] != want {
   276→					t.Errorf("FilterAndNormalizePaths()[%d] = %v, want %v", i, got[i], want)
   277→				}
   278→			}
   279→		})

