   234→// GetLatestCheckpointIDFromHistory walks backwards from HEAD and returns
   235→// the checkpoint ID from the first commit with an Entire-Checkpoint trailer.
   236→// Returns an error if no checkpoint trailer is found in any commit.
   237→func GetLatestCheckpointIDFromHistory(t *testing.T, repoDir string) (string, error) {
   238→	t.Helper()
   239→
   240→	repo, err := git.PlainOpen(repoDir)
   241→	if err != nil {
   242→		t.Fatalf("failed to open git repo: %v", err)
   243→	}
   244→
   245→	head, err := repo.Head()
   246→	if err != nil {
   247→		t.Fatalf("failed to get HEAD: %v", err)
   248→	}
   249→
   250→	commitIter, err := repo.Log(&git.LogOptions{From: head.Hash()})
   251→	if err != nil {
   252→		t.Fatalf("failed to iterate commits: %v", err)
   253→	}
   254→
   255→	var checkpointID string
   256→	//nolint:errcheck,gosec // ForEach callback returns error to stop iteration
   257→	commitIter.ForEach(func(c *object.Commit) error {
   258→		// Look for Entire-Checkpoint trailer
   259→		for line := range strings.SplitSeq(c.Message, "\n") {
   260→			line = strings.TrimSpace(line)
   261→			if value, found := strings.CutPrefix(line, "Entire-Checkpoint:"); found {
   262→				checkpointID = strings.TrimSpace(value)
   263→				return errors.New("stop iteration")
   264→			}
   265→		}
   266→		return nil
   267→	})
   268→
   269→	if checkpointID == "" {
   270→		return "", errors.New("no commit with Entire-Checkpoint trailer found in history")
   271→	}
   272→
   273→	return checkpointID, nil
   274→}
