   276→// SafeIDPrefix returns first 12 chars of ID or the full ID if shorter.
   277→// Use this when logging checkpoint IDs to avoid index out of bounds panic.
   278→func SafeIDPrefix(id string) string {
   279→	if len(id) >= 12 {
   280→		return id[:12]
   281→	}
   282→	return id
   283→}
