   285→// gitEmptyConfigPath returns the path to an empty file suitable for use as
   286→// GIT_CONFIG_GLOBAL/GIT_CONFIG_SYSTEM. We use an empty file instead of
   287→// os.DevNull because git on Windows cannot open NUL as a config file.
   288→var gitEmptyConfig string
   289→
   290→func gitEmptyConfigPath() string {
   291→	if gitEmptyConfig == "" {
   292→		f, err := os.CreateTemp("", "git-empty-config-*")
   293→		if err != nil {
   294→			panic("create empty git config: " + err.Error())
   295→		}
   296→		_ = f.Close()
   297→		gitEmptyConfig = f.Name()
   298→	}
   299→	return gitEmptyConfig
   300→}
