   302→// GitIsolatedEnv returns os.Environ() with git isolation variables set.
   303→// This prevents user/system git config (global gitignore, aliases, etc.) from
   304→// affecting test behavior. Use this for any exec.Command that runs git or the
   305→// CLI binary in integration tests.
   306→//
   307→// See https://git-scm.com/docs/git#Documentation/git.txt-GITCONFIGGLOBAL
   308→//
   309→// Existing GIT_CONFIG_GLOBAL/GIT_CONFIG_SYSTEM entries are filtered out before
   310→// appending overrides to ensure they take effect regardless of parent env.
   311→func GitIsolatedEnv() []string {
   312→	env := os.Environ()
   313→	filtered := make([]string, 0, len(env)+2)
   314→	for _, e := range env {
   315→		if strings.HasPrefix(e, "GIT_CONFIG_GLOBAL=") || strings.HasPrefix(e, "GIT_CONFIG_SYSTEM=") {
   316→			continue
   317→		}
   318→		filtered = append(filtered, e)
   319→	}
   320→	return append(filtered,
   321→		"GIT_CONFIG_GLOBAL="+gitEmptyConfigPath(), // Isolate from user's global git config (e.g. global gitignore)
   322→		"GIT_CONFIG_SYSTEM="+gitEmptyConfigPath(), // Isolate from system git config
   323→	)
   324→}
