// TestFilterToUncommittedFiles_CRLF verifies that a file committed with LF line
// endings but present on disk with CRLF (Windows autocrlf) is treated as already
// committed and excluded from the result.
func TestFilterToUncommittedFiles_CRLF(t *testing.T) {
	tmpDir := t.TempDir()
	t.Chdir(tmpDir)

	repo, err := git.PlainInit(tmpDir, false)
	if err != nil {
		t.Fatalf("git init: %v", err)
	}

	// Write file with LF, commit it, then replace on disk with CRLF.
	filePath := filepath.Join(tmpDir, "file.md")
	if err := os.WriteFile(filePath, []byte("hello\nworld\n"), 0o644); err != nil {
		t.Fatalf("write: %v", err)
	}

	wt, err := repo.Worktree()
	if err != nil {
		t.Fatalf("worktree: %v", err)
	}
	if _, err := wt.Add("file.md"); err != nil {
		t.Fatalf("add: %v", err)
	}
	if _, err := wt.Commit("init", &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "t@t.com"},
	}); err != nil {
		t.Fatalf("commit: %v", err)
	}

	// Simulate Windows autocrlf: overwrite disk file with CRLF content.
	if err := os.WriteFile(filePath, []byte("hello\r\nworld\r\n"), 0o644); err != nil {
		t.Fatalf("write crlf: %v", err)
	}

	result := filterToUncommittedFiles(context.Background(), []string{"file.md"}, tmpDir)
	require.Empty(t, result, "CRLF on disk should match LF in HEAD — file should not appear as uncommitted")
}

// TestFilterToUncommittedFiles_CRLF_BinaryUntouched verifies that binary files
// (those containing null bytes) are not CRLF-normalized.
func TestFilterToUncommittedFiles_CRLF_BinaryUntouched(t *testing.T) {
	tmpDir := t.TempDir()
	t.Chdir(tmpDir)

	repo, err := git.PlainInit(tmpDir, false)
	if err != nil {
		t.Fatalf("git init: %v", err)
	}

	// Commit binary content with a null byte.
	binaryLF := []byte("data\r\nmore\x00bytes\r\n")
	filePath := filepath.Join(tmpDir, "binary.bin")
	if err := os.WriteFile(filePath, binaryLF, 0o644); err != nil {
		t.Fatalf("write: %v", err)
	}

	wt, err := repo.Worktree()
	if err != nil {
		t.Fatalf("worktree: %v", err)
	}
	if _, err := wt.Add("binary.bin"); err != nil {
		t.Fatalf("add: %v", err)
	}
	if _, err := wt.Commit("init", &git.CommitOptions{
		Author: &object.Signature{Name: "Test", Email: "t@t.com"},
	}); err != nil {
		t.Fatalf("commit: %v", err)
	}

	// Disk content is identical (binary, null byte present) — should be committed.
	result := filterToUncommittedFiles(context.Background(), []string{"binary.bin"}, tmpDir)
	require.Empty(t, result, "binary file on disk matching HEAD should not appear as uncommitted")
}

