// filterTestRunGit runs a git command in dir for test setup, fataling on error.
func filterTestRunGit(t *testing.T, dir string, args ...string) {
	t.Helper()
	cmd := exec.Command("git", args...) //nolint:gosec
	cmd.Dir = dir
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("git %v failed: %v\n%s", args, err, out)
	}
}

// filterTestInitRepo initializes an isolated git repo for filterToUncommittedFiles tests.
func filterTestInitRepo(t *testing.T, dir string) {
	t.Helper()
	filterTestRunGit(t, dir, "init")
	filterTestRunGit(t, dir, "config", "user.name", "Test")
	filterTestRunGit(t, dir, "config", "user.email", "t@t.com")
	filterTestRunGit(t, dir, "config", "commit.gpgsign", "false")
}

// TestFilterToUncommittedFiles_CRLF verifies that a file committed with
// core.autocrlf=true (CRLF on disk, LF in blob) is not treated as uncommitted.
// This is the canonical Windows workflow: agents write CRLF files, git normalises
// them to LF in the object store, and git diff HEAD sees no change on checkout.
func TestFilterToUncommittedFiles_CRLF(t *testing.T) {
	t.Parallel()
	tmpDir := t.TempDir()

	filterTestInitRepo(t, tmpDir)
	// Enable autocrlf so git normalises CRLF→LF on add, LF→CRLF on checkout.
	filterTestRunGit(t, tmpDir, "config", "core.autocrlf", "true")

	filePath := filepath.Join(tmpDir, "file.md")
	// Write CRLF content; git add will normalise to LF in the blob.
	if err := os.WriteFile(filePath, []byte("hello\r\nworld\r\n"), 0o644); err != nil {
		t.Fatalf("write: %v", err)
	}
	filterTestRunGit(t, tmpDir, "add", "file.md")
	filterTestRunGit(t, tmpDir, "commit", "-m", "init")

	// Disk still has CRLF — git diff HEAD should report no change with autocrlf=true.
	result := filterToUncommittedFiles(context.Background(), []string{"file.md"}, tmpDir)
	require.Empty(t, result, "CRLF on disk should not appear uncommitted when autocrlf=true normalises to LF in HEAD")
}

// TestFilterToUncommittedFiles_CRLF_BinaryUntouched verifies that binary files
// (those containing null bytes) committed unchanged are filtered out.
func TestFilterToUncommittedFiles_CRLF_BinaryUntouched(t *testing.T) {
	t.Parallel()
	tmpDir := t.TempDir()

	filterTestInitRepo(t, tmpDir)
	filterTestRunGit(t, tmpDir, "config", "core.autocrlf", "false")

	binaryContent := []byte("data\r\nmore\x00bytes\r\n")
	filePath := filepath.Join(tmpDir, "binary.bin")
	if err := os.WriteFile(filePath, binaryContent, 0o644); err != nil {
		t.Fatalf("write: %v", err)
	}
	filterTestRunGit(t, tmpDir, "add", "binary.bin")
	filterTestRunGit(t, tmpDir, "commit", "-m", "init")

	// Disk content is identical — git diff HEAD should report no change.
	result := filterToUncommittedFiles(context.Background(), []string{"binary.bin"}, tmpDir)
	require.Empty(t, result, "binary file matching HEAD should not appear as uncommitted")
}

// TestFilterToUncommittedFiles_AlreadyCommitted verifies that a committed,
// unmodified file is excluded from the result.
func TestFilterToUncommittedFiles_AlreadyCommitted(t *testing.T) {
	t.Parallel()
	tmpDir := t.TempDir()

	filterTestInitRepo(t, tmpDir)
	filterTestRunGit(t, tmpDir, "config", "core.autocrlf", "false")

	filePath := filepath.Join(tmpDir, "file.txt")
	if err := os.WriteFile(filePath, []byte("hello\n"), 0o644); err != nil {
		t.Fatalf("write: %v", err)
	}
	filterTestRunGit(t, tmpDir, "add", "file.txt")
	filterTestRunGit(t, tmpDir, "commit", "-m", "init")

	result := filterToUncommittedFiles(context.Background(), []string{"file.txt"}, tmpDir)
	require.Empty(t, result, "already-committed unmodified file should be filtered out")
}

// TestFilterToUncommittedFiles_Modified verifies that a file modified after
// its last commit is retained in the result.
func TestFilterToUncommittedFiles_Modified(t *testing.T) {
	t.Parallel()
	tmpDir := t.TempDir()

	filterTestInitRepo(t, tmpDir)
	filterTestRunGit(t, tmpDir, "config", "core.autocrlf", "false")

	filePath := filepath.Join(tmpDir, "file.txt")
	if err := os.WriteFile(filePath, []byte("original\n"), 0o644); err != nil {
		t.Fatalf("write: %v", err)
	}
	filterTestRunGit(t, tmpDir, "add", "file.txt")
	filterTestRunGit(t, tmpDir, "commit", "-m", "init")

	// Modify the file after committing.
	if err := os.WriteFile(filePath, []byte("modified\n"), 0o644); err != nil {
		t.Fatalf("write modified: %v", err)
	}

	result := filterToUncommittedFiles(context.Background(), []string{"file.txt"}, tmpDir)
	require.Equal(t, []string{"file.txt"}, result, "modified file should be retained as uncommitted")
}

// TestFilterToUncommittedFiles_FailOpen verifies that if git diff fails
// (directory is not a git repository), the original file list is returned unchanged.
func TestFilterToUncommittedFiles_FailOpen(t *testing.T) {
	t.Parallel()
	tmpDir := t.TempDir() // no git init — git diff will fail

	files := []string{"file.txt", "other.txt"}
	result := filterToUncommittedFiles(context.Background(), files, tmpDir)
	require.Equal(t, files, result, "should fail open and return original file list when not in a git repo")
}

